contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;
        require(bankBefore == address(this));
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        address bankAfter = c.bank(); if (__ESBMC_reverted()) return;
        // The bank address is immutable: no play() call, succeeding or reverting,
        // with any amount of Ether, may change who the beneficiary is.
        assert(bankAfter == bankBefore);
    }

    receive() external payable {}
}

